<script dangerouslySetInnerHTML={{__html:"\r\n  function ytNextThumb(img) {\r\n    var order = ['oar2', 'maxresdefault', 'sddefault', 'hqdefault'];\r\n    var now = order.indexOf(img.src.split('/').pop().replace('.jpg', ''));\r\n    if (now < order.length - 1) {\r\n      img.src = img.src.replace(order[now] + '.jpg', order[now + 1] + '.jpg');\r\n    }\r\n  }\r\n  function ytCheckThumb(img) {\r\n    /* YouTube sometimes sends a tiny grey picture instead of an error */\r\n    if (img.naturalWidth > 0 && img.naturalWidth < 200) { ytNextThumb(img); }\r\n  }\r\n  "}} />


   
