<script dangerouslySetInnerHTML={{__html:"\r\n  (function(){\r\n    var track    = document.getElementById('testimonialsTrack');\r\n    var prevBtn  = document.getElementById('testimonialsPrevBtn');\r\n    var nextBtn  = document.getElementById('testimonialsNextBtn');\r\n    var dotsWrap = document.getElementById('testimonialsDots');\r\n    if (!track) return;\r\n\r\n    var cards = track.querySelectorAll('.testimonial-card');\r\n    var total = cards.length;\r\n    var current = 0;\r\n    var gap = 20;\r\n\r\n    /* ---- Carousel ---- */\r\n    function visibleCount() {\r\n      var w = window.innerWidth;\r\n      if (w >= 1100) return 4;\r\n      if (w >= 700)  return 2;\r\n      return 1;\r\n    }\r\n\r\n    function buildDots() {\r\n      dotsWrap.innerHTML = '';\r\n      var pages = Math.ceil(total / visibleCount());\r\n      for (var i = 0; i < pages; i++) {\r\n        var btn = document.createElement('button');\r\n        btn.className = 'testimonials-dot' + (i === 0 ? ' active' : '');\r\n        btn.setAttribute('aria-label', 'Page ' + (i + 1));\r\n        btn.dataset.page = i;\r\n        btn.addEventListener('click', function(){ goTo(+this.dataset.page * visibleCount()); });\r\n        dotsWrap.appendChild(btn);\r\n      }\r\n    }\r\n\r\n    function updateDots() {\r\n      var activePage = Math.round(current / visibleCount());\r\n      dotsWrap.querySelectorAll('.testimonials-dot').forEach(function(d, i){\r\n        d.classList.toggle('active', i === activePage);\r\n      });\r\n    }\r\n\r\n    function goTo(index) {\r\n      var vc = visibleCount();\r\n      var max = total - vc;\r\n      current = Math.max(0, Math.min(index, max));\r\n      var cardW = cards[0].offsetWidth + gap;\r\n      track.style.transform = 'translateX(-' + (current * cardW) + 'px)';\r\n      prevBtn.disabled = current === 0;\r\n      nextBtn.disabled = current >= total - vc;\r\n      updateDots();\r\n    }\r\n\r\n    prevBtn.addEventListener('click', function(){ goTo(current - visibleCount()); });\r\n    nextBtn.addEventListener('click', function(){ goTo(current + visibleCount()); });\r\n    window.addEventListener('resize', function(){ buildDots(); goTo(0); });\r\n\r\n    buildDots();\r\n    goTo(0);\r\n\r\n    /* SPEED: light YouTube player.\r\n       Click a thumbnail -> the real video loads and plays.\r\n       Any other video that was playing goes back to its thumbnail (only one plays at a time). */\r\n    function resetVideo(wrap) {\r\n      var id = wrap.getAttribute('data-id');\r\n      var title = wrap.getAttribute('data-title');\r\n      wrap.innerHTML = '<img src=\"https://i.ytimg.com/vi/' + id + '/oar2.jpg\" onerror=\"ytNextThumb(this)\" onload=\"ytCheckThumb(this)\" alt=\"DizitalAdda ' + title.toLowerCase() + ' video\" decoding=\"async\" width=\"1080\" height=\"1920\">' +\r\n        '<button class=\"yt-play\" type=\"button\" aria-label=\"Play ' + title + '\"></button>';\r\n      wrap.classList.remove('is-playing');\r\n    }\r\n    track.querySelectorAll('.yt-lite').forEach(function (wrap) {\r\n      wrap.addEventListener('click', function () {\r\n        if (wrap.classList.contains('is-playing')) return;\r\n        track.querySelectorAll('.yt-lite.is-playing').forEach(resetVideo);\r\n        var id = wrap.getAttribute('data-id');\r\n        wrap.innerHTML = '<iframe src=\"https://www.youtube-nocookie.com/embed/' + id + '?autoplay=1&rel=0\" title=\"' + wrap.getAttribute('data-title') + '\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen></iframe>';\r\n        wrap.classList.add('is-playing');\r\n      });\r\n    });\r\n    /* Moving the slider stops the playing video */\r\n    prevBtn.addEventListener('click', function(){ track.querySelectorAll('.yt-lite.is-playing').forEach(resetVideo); });\r\n    nextBtn.addEventListener('click', function(){ track.querySelectorAll('.yt-lite.is-playing').forEach(resetVideo); });\r\n  })();\r\n  "}} />

  
  

