<script dangerouslySetInnerHTML={{__html:"\r\n  (function () {\r\n    var photos = document.querySelectorAll('.campus-photo[data-bg]');\r\n    function show(el) { el.style.backgroundImage = \"url('\" + el.getAttribute('data-bg') + \"')\"; }\r\n    if (!('IntersectionObserver' in window)) { photos.forEach(show); return; }\r\n    var io = new IntersectionObserver(function (entries) {\r\n      entries.forEach(function (e) {\r\n        if (e.isIntersecting) { show(e.target); io.unobserve(e.target); }\r\n      });\r\n    }, { rootMargin: '300px' });\r\n    photos.forEach(function (el) { io.observe(el); });\r\n  })();\r\n  "}} />


  
