<script dangerouslySetInnerHTML={{__html:"\r\n/* Live Projects ? Stacked Deck Scroll */\r\n(function () {\r\n  var wrapper = document.getElementById('lpScrollWrapper');\r\n  if (!wrapper) return;\r\n  var stage   = document.getElementById('lpCardsStage');\r\n  var cards   = Array.prototype.slice.call(wrapper.querySelectorAll('.lp-scroll-card'));\r\n  var dots    = Array.prototype.slice.call(document.querySelectorAll('#lpDeckDots .lp-deck-dot'));\r\n  var total   = cards.length;\r\n\r\n  /* Set base z-index: card 0 on top */\r\n  cards.forEach(function (card, i) {\r\n    card.style.zIndex = String(total - i + 10);\r\n  });\r\n\r\n  /* -- Dot active state -- */\r\n  var numPrev = document.getElementById('lpNumPrev');\r\n  var numCurr = document.getElementById('lpNumCurr');\r\n  var numNext = document.getElementById('lpNumNext');\r\n  function setDot(index) {\r\n    dots.forEach(function (d, i) { d.classList.toggle('active', i === index); });\r\n    if (numCurr) {\r\n      numCurr.classList.remove('lp-num--pop');\r\n      void numCurr.offsetWidth; // force reflow so animation restarts\r\n      numPrev.textContent = index > 0 ? String(index) : '';\r\n      numCurr.textContent = String(index + 1);\r\n      numNext.textContent = index < total - 1 ? String(index + 2) : '';\r\n      numCurr.classList.add('lp-num--pop');\r\n    }\r\n  }\r\n\r\n  /* -- Mobile: dot tap switches card -- */\r\n  var mobileActive = 0;\r\n  function setMobile(index) {\r\n    mobileActive = index;\r\n    cards.forEach(function (card, i) { card.classList.toggle('lp-active', i === index); });\r\n    setDot(index);\r\n  }\r\n  setMobile(0);\r\n\r\n  /* -- Mobile autoplay -- */\r\n  var mobileAutoTimer = null;\r\n  function startMobileAuto() {\r\n    if (mobileAutoTimer) clearInterval(mobileAutoTimer);\r\n    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;\r\n    mobileAutoTimer = setInterval(function () {\r\n      if (window.innerWidth <= 900) {\r\n        setMobile((mobileActive + 1) % total);\r\n      }\r\n    }, 3500);\r\n  }\r\n  function stopMobileAuto() {\r\n    if (mobileAutoTimer) { clearInterval(mobileAutoTimer); mobileAutoTimer = null; }\r\n  }\r\n  if (window.innerWidth <= 900) startMobileAuto();\r\n\r\n  dots.forEach(function (dot, i) {\r\n    dot.addEventListener('click', function () {\r\n      if (window.innerWidth <= 900) {\r\n        setMobile(i);\r\n        startMobileAuto(); /* restart timer after manual tap */\r\n      } else {\r\n        var scrollable = wrapper.offsetHeight - window.innerHeight;\r\n        var unit = scrollable / (total - 1);\r\n        var target = wrapper.getBoundingClientRect().top + window.pageYOffset + i * unit;\r\n        window.scrollTo({ top: target, behavior: 'smooth' });\r\n      }\r\n    });\r\n  });\r\n\r\n  /* -- Desktop: scroll-driven stacked deck -- */\r\n  function onScroll() {\r\n    if (window.innerWidth <= 900) {\r\n      cards.forEach(function (card) {\r\n        card.style.removeProperty('transform');\r\n        card.style.removeProperty('opacity');\r\n      });\r\n      return;\r\n    }\r\n\r\n    var stageH   = stage.offsetHeight;\r\n    var scrolled = -wrapper.getBoundingClientRect().top;\r\n    var scrollable = wrapper.offsetHeight - window.innerHeight;\r\n    if (scrollable <= 0) return;\r\n\r\n    scrolled = Math.max(0, Math.min(scrollable, scrolled));\r\n\r\n    /* activeFloat: 0 = first card centre, (total-1) = last card centre */\r\n    var activeFloat = (scrolled / scrollable) * (total - 1);\r\n    var nearest = Math.round(activeFloat);\r\n\r\n    cards.forEach(function (card, i) {\r\n      var rel = i - activeFloat; /* <0 = gone above, 0 = active, >0 = in stack below */\r\n      var yPx, sc, op;\r\n\r\n      if (rel <= 0) {\r\n        /* Peel upward ? slides off the top of the deck */\r\n        var t = Math.min(1, -rel);\r\n        yPx = -t * stageH;\r\n        sc  = 1 - t * 0.06;\r\n        op  = 1 - t;\r\n      } else {\r\n        /* Stack peek ? each subsequent card is lower and slightly smaller */\r\n        var clamp = Math.min(rel, 3);\r\n        yPx = clamp * 22;\r\n        sc  = 1 - clamp * 0.04;\r\n        op  = rel < 3.5 ? 1 : 0;\r\n      }\r\n\r\n      card.style.setProperty('transform',\r\n        'translateY(calc(-50% + ' + yPx.toFixed(1) + 'px)) scale(' + sc.toFixed(3) + ')',\r\n        'important');\r\n      card.style.setProperty('opacity',\r\n        String(Math.max(0, Math.min(1, op)).toFixed(3)),\r\n        'important');\r\n    });\r\n\r\n    setDot(Math.max(0, Math.min(total - 1, nearest)));\r\n  }\r\n\r\n  window.addEventListener('scroll', onScroll, { passive: true });\r\n  window.addEventListener('resize', function () {\r\n    onScroll();\r\n    if (window.innerWidth <= 900) {\r\n      if (!mobileAutoTimer) startMobileAuto();\r\n    } else {\r\n      stopMobileAuto();\r\n    }\r\n  }, { passive: true });\r\n  onScroll();\r\n})();\r\n"}} />





